```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None


class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def remove(self, key):
        head_val = self.head

        if head_val is not None:
            if head_val.data == key:
                self.head = head_val.next
                head_val = None
                return

        while head_val is not None:
            if head_val.data == key:
                break
            prev = head_val
            head_val = head_val.next

        if head_val is None:
            return

        prev.next = head_val.next
        head_val = None

    def search(self, key):
        current = self.head
        while current is not None:
            if current.data == key:
                return True
            current = current.next
        return False

    def display(self):
        val = self.head
        while val is not None:
            print(val.data, end=' ')
            val = val.next
        print()
